                $response = $this->nextHandler->job($_request);
            }
        }
        return $response;
    }

    public function setNext(Handler $_handler) {
        $this->nextHandler = $_handler;
    }

    // Handle urgency level
    abstract function getEmerLevel();

    // Handle task
    abstract function report();
}

