class Facade {
    private $objOne;
    private $objTwo;
    private $objThree;
    private $context;

    public function __construct()
    {
        $this->objOne = new SubsystemOne();
        $this->objTwo = new SubsystemTwo();
        $this->objThr = new SubsystemThr();
        $this->context = new Context();
