class Context {
    private $objOne;
    private $objThr;

    public function __construct()
    {
        $this->objOne = new SubsystemOne();
        $this->objThr = new SubsystemThr();
    }

    public function combineJob()
    {
        $this->objOne->doSthFir();
        $this->objThr->doSthThr();
    }
}

